function bytesToHex(bytes) {
    var hex = [];
    for (var i = 0; i < bytes.length; i++) {
        hex.push(HEX_CHARS[bytes[i]]);
    }

    return hex.join('');
}

/**
 * Convert a hex string to a byte array
 *
 * @param {string} str
 * @returns {string}
