void *my_malloc(size_t size)
{
    if (size == 0) {
        return NULL;
    }

    /* Round up to multiple of 8 bytes */
    size = (size + 7) & ~7;

    /* Check if we have a free block of the right size */
    struct node **prev = &free_list;
    struct node *current = free_list;
    while (current != NULL) {
        if (current->size >= size) {
            /* Found a block that fits */
            *prev = current->next; /* Remove from free list */
            current->size = size;  /* Set actual size */
            return (void *)current + sizeof(struct node);
        }
        prev = &current->next;
        current = current->next;
    }

    /* No suitable block found, allocate new one */
    struct node *new_node = malloc(sizeof(struct node) + size);
    if (new_node == NULL) {
        return NULL;
    }
    new_node->size = size;
    new_node->next = NULL;
    return (void *)new_node + sizeof(struct node);
}

void my_free(void *ptr)
{
    if (ptr == NULL) {
        return;
    }

    /* Get pointer to the node header */
    struct node *node = (struct node *)((char *)ptr - sizeof(struct node));

    /* Add to free list */
    node->next = free_list;
    free_list = node;

    /* Replenish the free list if needed */
    replenish_free_list();
}
