XHRFormat::XHRFormat(const std::string& url) : m_url(url) {
    if (m_url.find("http://") == 0) {
        m_protocol = "http";
        m_host = m_url.substr(7);
    } else if (m_url.find("https://") == 0) {
        m_protocol = "https";
        m_host = m_url.substr(8);
    } else {
        throw std::runtime_error("Invalid URL: " + m_url);
    }

    size_t pos = m_host.find('/');
    if (pos != std::string::npos) {
        m_path = m_host.substr(pos);
        m_host = m_host.substr(0, pos);
    } else {
        m_path = "/";
    }

    pos = m_host.find(':');
    if (pos != std::string::npos) {
        m_port = std::stoi(m_host.substr(pos + 1));
        m_host = m_host.substr(0, pos);
    } else {
        m_port = (m_protocol == "https") ? 443 : 80;
    }
}

