#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;
        string path = "";
        backtrack(res, path, 0, 0, n);
        return res;
    }

    void backtrack(vector<string>& res, string path, int left, int right, int n) {
        if (path.size() == 2 * n) {
            res.push_back(path);
            return;
        }

        if (left < n) {
            path += '(';
            backtrack(res, path, left + 1, right, n);
            path.pop_back();
        }

        if (right < left) {
            path += ')';
            backtrack(res, path, left, right + 1, n);
            path.pop_back();
        }
    }
};

int main() {
    Solution s;
    vector<string> res = s.generateParenthesis(3);
    for (auto& str : res) {
        cout << str << " ";
    }
    cout << endl;
    return 0;
}
