TRACEFormat::TRACEFormat(const std::string &filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file: " + filename);
    }

    std::string line;
    while (std::getline(file, line)) {
        if (line.empty() || line[0] == '#') {
            continue;
        }

        std::istringstream iss(line);
        std::string type, name, value;

        if (std::getline(iss, type, ',') && std::getline(iss, name, ',') && std::getline(iss, value)) {
            // Remove leading/trailing whitespace
            type.erase(0, type.find_first_not_of(" \t"));
            type.erase(type.find_last_not_of(" \t") + 1);
            name.erase(0, name.find_first_not_of(" \t"));
            name.erase(name.find_last_not_of(" \t") + 1);
            value.erase(0, value.find_first_not_of(" \t"));
            value.erase(value.find_last_not_of(" \t") + 1);

            if (type == "event") {
                events[name] = value;
            } else if (type == "field") {
                fields[name] = value;
            } else if (type == "format") {
                formats[name] = value;
            }
        }
    }

    file.close();
}

.PrimaryKeyFrame::PrimaryKeyFrame(const uint8_t* data, size_t size) {
    if (size < sizeof(PrimaryKeyFrameHeader)) {
        throw std::runtime_error("Invalid PrimaryKeyFrame");
    }

    const PrimaryKeyFrameHeader* header = reinterpret_cast<const PrimaryKeyFrameHeader*>(data);
    if (header->magic != PrimaryKeyFrameHeader::kMagic) {
        throw std::runtime_error("Invalid PrimaryKeyFrame magic");
    }

    if (header->version != PrimaryKeyFrameHeader::kVersion) {
        throw std::runtime_error("Invalid PrimaryKeyFrame version");
    }

    if (header->key_size == 0) {
        throw std::runtime_error("Invalid PrimaryKeyFrame key_size");
    }

    if (size != sizeof(PrimaryKeyFrameHeader) + header->key_size) {
        throw std::runtime_error("Invalid PrimaryKeyFrame size");
    }

    key_ = std::string(reinterpret_cast<const char*>(data + sizeof(PrimaryKeyFrameHeader)),
                       header->key_size);
}

